function optimizeModel(root){root.traverse(group=>{if(group.isMesh)return;const batches=new Map();for(const child of [...group.children]){if(!child.isMesh)continue;child.updateMatrix();let b=batches.get(child.material.uuid);if(!b){b={material:child.material,geometries:[]};batches.set(child.material.uuid,b);}const geometry=child.geometry.clone();geometry.applyMatrix4(child.matrix);if(!geometry.attributes.uv)geometry.setAttribute('uv',new T.BufferAttribute(new Float32Array(geometry.attributes.position.count*2),2));b.geometries.push(geometry.index?geometry.toNonIndexed():geometry);group.remove(child);}for(const b of batches.values()){const geometry=mergeGeometries(b.geometries);if(geometry)group.add(new T.Mesh(geometry,b.material));b.geometries.forEach(g=>g.dispose());}});}
function cloneModel(name){const model=prefabs[name].clone(true),materials=new Map();model.traverse(o=>{if(!o.isMesh)return;o.castShadow=true;o.receiveShadow=true;const key=o.material.uuid;if(!materials.has(key)){const m=o.material.clone();m.userData.baseEmissive=m.emissive.clone();materials.set(key,m);}o.material=materials.get(key);});return model;}
function getRig(root){const rig={body:root.getObjectByName('body'),arms:[],legs:[]};root.traverse(o=>{if(o.name.startsWith('leg'))rig.legs.push(o);if(o.name.startsWith('arm'))rig.arms.push(o);});return rig;}
function spawnEnemy(type,x,z){const data=ENEMY_TYPES[type],name=type==='hound'?'grave-hound':type==='boss'?'bellkeeper':type;const model=cloneModel(name);model.position.set(x,0,z);model.rotation.y=Math.random()*6.28;scene.add(model);const e={type,data,model,rig:getRig(model),hp:data.hp,maxHp:data.hp,phase:'idle',timer:0,cooldown:1+Math.random()*1.5,angle:0,attackAngle:0,aim:new T.Vector3(),flash:0,dead:false,home:{x,z},attackCount:0,seed:Math.random()*6.28,telegraph:null,path:[],navTimer:0,bar:null,barCanvas:null,barTexture:null};
 const c=document.createElement('canvas');c.width=128;c.height=12;const texture=new T.CanvasTexture(c);const bar=new T.Sprite(new T.SpriteMaterial({map:texture,transparent:true,depthTest:false,depthWrite:false}));bar.scale.set(type==='boss'?2.3:1.1,.10,1);bar.visible=false;scene.add(bar);e.bar=bar;e.barCanvas=c;e.barTexture=texture;updateEnemyBar(e);enemies.push(e);return e;}
function updateEnemyBar(e){const c=e.barCanvas.getContext('2d');c.clearRect(0,0,128,12);c.fillStyle='#131b19';c.fillRect(0,0,128,12);c.fillStyle='#b66b51';c.fillRect(2,2,124*Math.max(0,e.hp/e.maxHp),8);c.strokeStyle='#b8a984';c.lineWidth=1;c.strokeRect(.5,.5,127,11);e.barTexture.needsUpdate=true;}
function resize(){if(!renderer)return;const w=innerWidth,h=innerHeight;renderer.setSize(w,h,false);const height=w<650?28:29;camera.left=-height*(w/h)/2;camera.right=-camera.left;camera.top=height/2;camera.bottom=-height/2;camera.updateProjectionMatrix();}
window.addEventListener('resize',resize);
function awaken(){if(!ready)return;started=true;audio.unlock().then(()=>{$('audio-prompt').style.opacity='0';$('sound-button').setAttribute('aria-label',audio.muted?'Enable sound':'Mute sound');});}
function getPointerWorld(){raycaster.setFromCamera(pointer,camera);raycaster.ray.intersectPlane(plane,targetWorld);}
function updatePointer(event){const rect=$('world').getBoundingClientRect();pointer.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);aimActive=true;if(ready)getPointerWorld();}
function enemyAtPoint(point){let best=null,bestD=1.45;for(const e of enemies){if(e.dead)continue;const d=distance(e.model.position,point);if(d<bestD+(e.type==='boss'?.6:0)){bestD=d;best=e;}}return best;}
function pickEnemy(){raycaster.setFromCamera(pointer,camera);const alive=enemies.filter(e=>!e.dead);const hits=raycaster.intersectObjects(alive.map(e=>e.model),true);if(hits.length){let object=hits[0].object;while(object&&object.parent!==scene)object=object.parent;return alive.find(e=>e.model===object)||null;}return enemyAtPoint(targetWorld);}
function setDestination(point){const path=findPath(player.position,point,environment.obstacles);if(!path.length){toast('That way is blocked.');return false;}movePath=path;const first=movePath.shift();moveTarget=new T.Vector3(first.x,0,first.z);lockedEnemy=null;attackHeld=false;groundPing(point);return true;}
function nearestEnemy(range=9){let best=null,dist=range;for(const e of enemies){if(e.dead)continue;const d=distance(player.position,e.model.position);if(d<dist){best=e;dist=d;}}return best;}
$('world').addEventListener('pointermove',updatePointer);
$('world').addEventListener('pointerdown',event=>{if(!ready||paused||state.ended&&!state.victory)return;event.preventDefault();$('world').focus({preventScroll:true});awaken();updatePointer(event);if(event.button===2){perform('bolt');return;}if(event.button!==0)return;const enemy=pickEnemy();lockedEnemy=enemy;if(enemy){attackHeld=true;moveTarget=null;angle=Math.atan2(enemy.model.position.x-player.position.x,enemy.model.position.z-player.position.z);if(distance(player.position,enemy.model.position)<3)perform('attack');}else if(event.shiftKey||distance(player.position,targetWorld)<2.4){moveTarget=null;attackHeld=true;perform('attack');}else{setDestination(targetWorld);}});
window.addEventListener('pointerup',event=>{if(event.button===0)attackHeld=false;});$('world').addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',event=>{if(event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement)return;const key=event.key.toLowerCase();if(event.target instanceof HTMLButtonElement&&[' ','enter'].includes(key))return;if([' ','arrowup','arrowdown','arrowleft','arrowright','tab'].includes(key)&&key!=='tab')event.preventDefault();if(event.repeat&&['escape','q','e','h','j','m'].includes(key))return;if(key==='escape'){if(mapExpanded)toggleMap();else if(paused)closeModal();else showModal('pause');return;}if(key==='h'){paused?closeModal():showModal('help');return;}if(key==='j'){paused?closeModal():showModal('journal');return;}if(key==='m'){toggleMap();return;}if(!ready||paused||state.ended&&!state.victory)return;keys.add(key);if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','e','q'].includes(key))awaken();if(key===' ')perform('dodge');if(key==='e')perform('nova');if(key==='q')perform('heal');});window.addEventListener('keyup',event=>keys.delete(event.key.toLowerCase()));
