$('sound-button').onclick=async()=>{await audio.unlock();const muted=audio.toggle();$('sound-button').innerHTML=icon(muted?'muted':'volume');$('sound-button').setAttribute('aria-label',muted?'Enable sound':'Mute sound');$('audio-prompt').style.opacity='0';toast(muted?'Sound muted':'Sound enabled');};$('help-button').onclick=()=>showModal('help');$('journal-button').onclick=()=>showModal('journal');$('pause-button').onclick=()=>showModal('pause');$('map-button').onclick=toggleMap;$('fullscreen-button').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else $('game').requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this view.'));};
function toggleMap(){if(!ready||state.ended)return;mapExpanded=!mapExpanded;document.querySelector('.map-panel').classList.toggle('expanded',mapExpanded);$('map-button').setAttribute('aria-label',mapExpanded?'Close map':'Expand map');paused=mapExpanded;keys.clear();attackHeld=false;audio.pause(paused);}
const joystick=$('joystick');joystick.addEventListener('pointerdown',event=>{if(paused||!ready)return;event.preventDefault();joystickPointer=event.pointerId;joystick.setPointerCapture(event.pointerId);awaken();updateJoystick(event);});joystick.addEventListener('pointermove',event=>{if(event.pointerId===joystickPointer)updateJoystick(event);});const releaseJoystick=()=>{joystickPointer=null;joystickValue={x:0,y:0};$('joystick-thumb').style.transform='';};joystick.addEventListener('pointerup',releaseJoystick);joystick.addEventListener('pointercancel',releaseJoystick);function updateJoystick(event){const r=joystick.getBoundingClientRect(),x=event.clientX-r.left-r.width/2,y=event.clientY-r.top-r.height/2,length=Math.hypot(x,y),scale=Math.min(34,length)/Math.max(1,length);joystickValue={x:x*scale/34,y:y*scale/34};$('joystick-thumb').style.transform=`translate(${x*scale}px,${y*scale}px)`;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2500);}
function perform(action){if(!ready||paused||state.ended)return false;if(!canUse(state,action)){if(state.cooldowns[action]>0)return false;if(action==='heal')toast(state.potions===0?'No draughts remaining.':'Your vitality is full.');else if(state.mana<ABILITIES[action].cost)toast('Not enough essence.');return false;}const hpBefore=state.hp;useAbility(state,action);if(!aimActive&&action!=='dodge'){const target=nearestEnemy(7);if(target)angle=Math.atan2(target.model.position.x-player.position.x,target.model.position.z-player.position.z);}player.rotation.y=angle;const forward=new T.Vector3(Math.sin(angle),0,Math.cos(angle));
 if(action==='attack'){heroRig.attack=.32;audio.play('sword',.53,.9+Math.random()*.2);slash(player.position,angle,0xe8d3a0,2.7,.28);pendingHits.push({time:.11,angle});}
 if(action==='bolt'){heroRig.attack=.3;audio.play('ember',.65,1.25);spawnProjectile(player.position.clone().add(new T.Vector3(0,1.1,0)).addScaledVector(forward,.8),forward,14,46+state.level*2,false,0xff9c43);spellLight.position.copy(player.position).add(new T.Vector3(0,1.6,0));spellLight.color.setHex(0xff903f);spellLight.intensity=55;}
 if(action==='nova'){audio.play('ember',.9,.68);ringEffect(player.position,0xf0a24c,.3,4.6,.65);particles(player.position.clone().add(new T.Vector3(0,.3,0)),0xffad52,70,5);spellLight.position.copy(player.position).add(new T.Vector3(0,2,0));spellLight.color.setHex(0xff9f42);spellLight.intensity=110;shake=reducedMotion?0:.1;for(const e of enemies)if(!e.dead&&distance(player.position,e.model.position)<4.6){damageEnemy(e,62+state.level*3,true);if(!e.dead)cancelAttack(e,.7);}}
 if(action==='dodge'){dodgeTime=.27;state.invulnerable=.48;dodgeVector.copy(lastMove);if(dodgeVector.lengthSq()<.1)dodgeVector.copy(forward);dodgeVector.normalize();moveTarget=null;lockedEnemy=null;audio.play('dodge',.6);particles(player.position.clone().add(new T.Vector3(0,.3,0)),0xb0c5b5,20,1.5);}
 if(action==='heal'){audio.play('heal',.7);floatText(`+${state.hp-hpBefore}`,player.position,'heal');ringEffect(player.position,0x97cba5,.2,1.5,.7);particles(player.position.clone(),0xc1d5a6,32,1.3);}
 const button=document.querySelector(`[data-action="${action}"]`);button?.classList.add('active');setTimeout(()=>button?.classList.remove('active'),130);updateUI();return true;}
function moveEntity(model,dx,dz,radius=.42){const p=resolveMove(model.position,dx,dz,environment.obstacles,radius,25);const moved=Math.hypot(p.x-model.position.x,p.z-model.position.z);model.position.x=p.x;model.position.z=p.z;return moved;}
function damageEnemy(e,amount,magic=false){if(e.dead)return;const dealt=Math.min(e.hp,amount);e.hp-=amount;e.flash=.14;floatText(String(dealt),e.model.position,magic?'magic':'');particles(e.model.position.clone().add(new T.Vector3(0,.9,0)),magic?0xffb565:0xc7b48a,magic?20:12,2);audio.play('impact',.35,.82+Math.random()*.3);shake=Math.max(shake,reducedMotion?0:.045);updateEnemyBar(e);if(e.hp<=0){e.dead=true;e.phase='dead';e.timer=1;cancelAttack(e);e.bar.visible=false;const oldLevel=state.level;const reward=awardKill(state,e.type);audio.play('death',e.type==='boss'?.8:.28,e.type==='boss'?.65:1.05);floatText(`+${reward} souls`,e.model.position,'small');if(state.level>oldLevel){toast(`Oath strengthened · Level ${state.level}`);audio.play('heal',.5,.8);ringEffect(player.position,0xd6c490,.2,2.7,1);}if(e.type==='boss'){ringEffect(e.model.position,0xbacdad,.5,12,2);audio.play('bell',.7,.8);setTimeout(()=>showModal('victory'),2200);}else if(state.kills===SPAWNS.length)spawnBoss();if(state.kills%4===0&&!state.ended){state.potions=Math.min(5,state.potions+1);toast('Healing draught recovered');audio.play('pickup',.3);}}}
function damagePlayer(amount){const dealt=hurtPlayer(state,amount);if(!dealt)return;floatText(String(dealt),player.position,'enemy-damage');audio.play('hurt',.6);shake=reducedMotion?0:.12;$('damage-vignette').style.opacity='.75';setTimeout(()=>$('damage-vignette').style.opacity='0',210);particles(player.position.clone().add(new T.Vector3(0,.8,0)),0xbb5944,12,1.5);if(state.ended){attackHeld=false;keys.clear();audio.play('death',.7,.7);setTimeout(()=>showModal('death'),1000);}}
function spawnBoss(){if(state.bossSpawned)return;state.bossSpawned=true;const boss=spawnEnemy('boss',0,-8.8);boss.cooldown=2.6;particles(boss.model.position,0xbc8660,70,4);ringEffect(boss.model.position,0xe29f6e,.2,3,1.4);audio.play('roar',.85,.7);audio.play('bell',.65);toast('The Bellkeeper has answered.');$('boss-bar').hidden=false;$('enemy-target').hidden=true;}
function groundPing(pos){ringEffect(pos,0xc0c2a1,.25,.65,.45);}
function ringEffect(pos,color,from,to,life){const mesh=new T.Mesh(new T.RingGeometry(.89,1,64),new T.MeshBasicMaterial({color,transparent:true,opacity:.8,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending}));mesh.rotation.x=-Math.PI/2;mesh.position.set(pos.x,.13,pos.z);scene.add(mesh);effects.push({type:'ring',mesh,time:0,life,from,to});}
function slash(pos,a,color,radius,life){const mesh=new T.Mesh(new T.RingGeometry(radius*.78,radius,38,1,-Math.PI/2-.72,1.44),new T.MeshBasicMaterial({color,transparent:true,opacity:.85,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending}));mesh.rotation.set(-Math.PI/2,0,a-.2);mesh.position.copy(pos).add(new T.Vector3(0,.85,0));scene.add(mesh);effects.push({type:'slash',mesh,time:0,life,angle:a});}
function particles(pos,color,count,speed){const values=new Float32Array(count*3),velocity=new Float32Array(count*3);for(let i=0;i<count;i++){velocity[i*3]=(Math.random()-.5)*speed*2;velocity[i*3+1]=Math.random()*speed+1;velocity[i*3+2]=(Math.random()-.5)*speed*2;}const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(values,3));const mesh=new T.Points(g,new T.PointsMaterial({color,size:.065,transparent:true,opacity:.9,depthWrite:false,blending:T.AdditiveBlending}));mesh.position.copy(pos);scene.add(mesh);effects.push({type:'particles',mesh,velocity,time:0,life:.75});}
function spawnProjectile(pos,dir,speed,damage,hostile,color=0xef7051){const mesh=new T.Group();mesh.position.copy(pos);const core=new T.Mesh(new T.SphereGeometry(hostile?.12:.15,8,6),new T.MeshBasicMaterial({color}));mesh.add(core);const sprite=new T.Sprite(new T.SpriteMaterial({map:environment.glowTexture,color,blending:T.AdditiveBlending,depthWrite:false,transparent:true,opacity:.85}));sprite.scale.set(hostile?.85:1.25,hostile?.85:1.25,1);mesh.add(sprite);scene.add(mesh);projectiles.push({mesh,dir:dir.clone().normalize(),speed,damage,hostile,color,life:2.5,trail:0});}
function telegraph(pos,radius,arc=Math.PI*2,a=0){const group=new T.Group();group.position.set(pos.x,.1,pos.z);const mat=new T.MeshBasicMaterial({color:0xe76042,transparent:true,opacity:.15,side:T.DoubleSide,depthWrite:false});const fill=new T.Mesh(new T.CircleGeometry(radius,48,-Math.PI/2-arc/2,arc),mat);fill.rotation.set(-Math.PI/2,0,a);group.add(fill);const edge=new T.Mesh(new T.RingGeometry(radius-.055,radius,48,1,-Math.PI/2-arc/2,arc),new T.MeshBasicMaterial({color:0xf59766,transparent:true,opacity:.85,depthWrite:false,side:T.DoubleSide}));edge.rotation.set(-Math.PI/2,0,a);group.add(edge);scene.add(group);return group;}
function removeObject(object){scene.remove(object);object.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose();}});}
